import{_ as e,a0 as l,w as o,s as r,ao as d,I as t,x as n,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"探索 Linux 上的 /run | LCTT x X-CMD","titleTemplate":false,"description":"探索 Linux 上的 /run | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"探索 Linux 上的 /run | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"探索 Linux 上的 /run | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190617 Exploring -run on Linux","title":"探索 Linux 上的 /run","tag":"201906","desc":""},"relativePath":"201906/20190617 Exploring -run on Linux.md","filePath":"[post].md"}'),u={name:"201906/20190617 Exploring -run on Linux.md"};function c(h,s,g,x,k,b){const a=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="探索-linux-上的-run" tabindex="-1">探索 Linux 上的 /run <a class="header-anchor" href="#探索-linux-上的-run" aria-label="Permalink to “探索 Linux 上的 /run”">​</a></h1><blockquote><p>Linux 系統在運行時數據方面的工作方式發生了微小但重大的變化。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201906/23/092816aqczi984w30j8k12.jpg" alt=""></p><p>如果你沒有密切關注，你可能沒有注意到 Linux 系統在運行時數據方面的工作方式有一些小但重大的變化。 它重新組織了文件系統中可訪問的方式和位置，而這個變化在大約八年前就開始了。雖然這種變化可能不足以讓你的襪子變濕，但它在 Linux 文件系統中提供了更多一致性，值得進行一些探索。</p><p>要開始，請轉到 <code>/run</code>。如果你使用 <code>df</code> 來檢查它，你會看到這樣的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -k .</span></span>
<span class="line"><span>Filesystem     1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>tmpfs             609984  2604    607380   1% /run</span></span></code></pre></div><p>它被識別為 “tmpfs”（臨時文件系統），因此我們知道 <code>/run</code> 中的文件和目錄沒有存儲在磁盤上，而只存儲在內存中。它們表示保存在內存（或基於磁盤的交換空間）中的數據，它看起來像是一個已掛載的文件系統，這個可以使其更易於訪問和管理。</p><p><code>/run</code> 是各種各樣數據的家園。例如，如果你查看 <code>/run/user</code>，你會注意到一組帶有數字名稱的目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /run/user</span></span>
<span class="line"><span>1000  1002  121</span></span></code></pre></div><p>使用長文件列表可以發現這些數字的重要性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>drwx------ 5 shs  shs  120 Jun 16 12:44 1000</span></span>
<span class="line"><span>drwx------ 5 dory dory 120 Jun 16 16:14 1002</span></span>
<span class="line"><span>drwx------ 8 gdm  gdm  220 Jun 14 12:18 121</span></span></code></pre></div><p>我們看到每個目錄與當前登錄的用户或顯示管理器 gdm 相關。數字代表他們的 UID。每個目錄的內容都是運行中的進程所使用的文件。</p><p><code>/run/user</code> 文件只是你在 <code>/run</code> 中找到的一小部分。還有很多其他文件。有一些文件包含了各種系統進程的進程 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.pid</span></span>
<span class="line"><span>acpid.pid  atopacctd.pid  crond.pid  rsyslogd.pid</span></span>
<span class="line"><span>atd.pid    atop.pid       gdm3.pid   sshd.pid</span></span></code></pre></div><p>如下所示，上面列出的 <code>sshd.pid</code> 文件包含 ssh 守護程序（<code>sshd</code>）的進程 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat sshd.pid</span></span>
<span class="line"><span>1148</span></span>
<span class="line"><span>$ ps -ef | grep sshd</span></span>
<span class="line"><span>root      1148     1  0 Jun14 ?        00:00:00 /usr/sbin/sshd -D    &lt;==</span></span>
<span class="line"><span>root     10784  1148  0 12:44 ?        00:00:00 sshd: shs [priv]</span></span>
<span class="line"><span>shs      10922 10784  0 12:44 ?        00:00:00 sshd: shs@pts/0</span></span>
<span class="line"><span>root     18109  1148  0 16:13 ?        00:00:00 sshd: dory [priv]</span></span>
<span class="line"><span>dory     18232 18109  0 16:14 ?        00:00:00 sshd: dory@pts/1</span></span>
<span class="line"><span>shs      19276 10923  0 16:50 pts/0    00:00:00 grep --color=auto sshd</span></span></code></pre></div><p><code>/run</code> 中的某些子目錄只能使用 root 權限訪問，例如 <code>/run/sudo</code>。例如，以 root 身份運行我們可以看到一些與真實或嘗試使用 <code>sudo</code> 相關的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/run/sudo/ts# ls -l</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>-rw------- 1 root dory 112 Jun 16 16:37 dory</span></span>
<span class="line"><span>-rw------- 1 root shs  168 Jun 17 08:33 shs</span></span></code></pre></div><p>為了與 <code>/run</code> 的變化保持一致，一些運行時數據的舊位置現在是符號鏈接。<code>/var/run</code> 現在是指向 <code>/run</code> 的指針，<code>/var/lock</code> 指向 <code>/run/lock</code> 的指針，可以保證舊的引用按預期工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var</span></span>
<span class="line"><span>total 52</span></span>
<span class="line"><span>drwxr-xr-x  2 root root     4096 Jun 17 07:36 backups</span></span>
<span class="line"><span>drwxr-xr-x 19 root root     4096 Apr 18 13:46 cache</span></span>
<span class="line"><span>drwxrwsrwt  2 root whoopsie 4096 Jun 13 07:39 crash</span></span>
<span class="line"><span>drwxr-xr-x 75 root root     4096 Jun  9 15:14 lib</span></span>
<span class="line"><span>drwxrwsr-x  2 root staff    4096 Oct 16  2017 local</span></span>
<span class="line"><span>lrwxrwxrwx  1 root root        9 May 14  2018 lock -&gt; /run/lock</span></span>
<span class="line"><span>drwxrwxr-x 17 root syslog   4096 Jun 17 00:00 log</span></span>
<span class="line"><span>drwxrwsrwt  2 root mail     4096 Jun 13 12:10 mail</span></span>
<span class="line"><span>drwxrwsrwt  2 root whoopsie 4096 Jan  5  2018 metrics</span></span>
<span class="line"><span>drwxr-xr-x  2 root root     4096 Jan  5  2018 opt</span></span>
<span class="line"><span>lrwxrwxrwx  1 root root        4 May 14  2018 run -&gt; /run</span></span>
<span class="line"><span>drwxr-xr-x  9 root root     4096 Jun 16  2018 snap</span></span>
<span class="line"><span>drwxr-xr-x  9 root root     4096 Jun  9 15:14 spool</span></span>
<span class="line"><span>drwxrwxrwt  8 root root     4096 Jun 17 00:00 tmp</span></span>
<span class="line"><span>drwxr-xr-x  3 root root     4096 Jan 19 12:14 www</span></span></code></pre></div><p>雖然技術上的變化很小，但轉換到使用 <code>/run</code> 只是為了在 Linux 文件系統中更好地組織運行時數據。</p><hr>`,22)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://www.networkworld.com/article/3403023/exploring-run-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3403023/exploring-run-on-linux.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),p(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const y=e(u,[["render",c]]);export{m as __pageData,y as default};
